const string W="D:/project/MTGB/design-demos/battlefield-redesign-2026-10-24/";
var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>();
if(ui==null)ui=new GameObject("RedesignPreview").AddComponent<ForgeBattlefieldController>();
if(!Application.isPlaying||UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!=ForgeBattlefieldController.SceneName)return "Open the duel battlefield in Play Mode.";
var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
var results=new System.Collections.Generic.List<object>();int checks=0,failed=0,calls=0,last=-1;string oldLanguage=GamePreferences.Language;float oldScale=GamePreferences.TextScale;
void Check(bool pass,string context){checks++;if(!pass)failed++;results.Add(new{pass,context});}
void Save(string status){var method=Type.GetType("Newtonsoft.Json.JsonConvert, Newtonsoft.Json").GetMethod("SerializeObject",new[]{typeof(object)});System.IO.File.WriteAllText(W+"opponent-horizontal-validation.json",(string)method.Invoke(null,new object[]{new{status,checks,failed,scope="Copied-scene display adapters and recorded native choice consumers; no live network or new engine effect claims",results}}));}
ForgeSeatView Read(string path)=>JsonUtility.FromJson<ForgeSeatView>(System.IO.File.ReadAllText(path));
ForgeSeatView Sample()=>Read(W+"native-full-seat.json");
T Clone<T>(T value)=>JsonUtility.FromJson<T>(JsonUtility.ToJson(value));
Transform Root()=>GameObject.Find("Canvas").transform;
Rect Bounds(RectTransform r){var c=new Vector3[4];r.GetWorldCorners(c);return Rect.MinMaxRect(c.Min(v=>v.x),c.Min(v=>v.y),c.Max(v=>v.x),c.Max(v=>v.y));}
bool Overlap(Rect a,Rect b)=>Mathf.Min(a.xMax,b.xMax)-Mathf.Max(a.xMin,b.xMin)>1&&Mathf.Min(a.yMax,b.yMax)-Mathf.Max(a.yMin,b.yMin)>1;
UnityEngine.EventSystems.PointerEventData Event(Vector2 p)=>new(UnityEngine.EventSystems.EventSystem.current){position=p,pressPosition=p,button=UnityEngine.EventSystems.PointerEventData.InputButton.Left,eligibleForClick=true};
GameObject Hit(Vector2 p){var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(Event(p),hits);return hits.FirstOrDefault().gameObject;}
bool Click(UnityEngine.UI.Button button){var b=Bounds((RectTransform)button.transform);foreach(float x in new[]{.5f,.1f,.9f})foreach(float y in new[]{.5f,.1f,.9f}){var p=new Vector2(Mathf.Lerp(b.xMin,b.xMax,x),Mathf.Clamp(Mathf.Lerp(b.yMin,b.yMax,y),2,Screen.height-2));var hit=Hit(p);if(hit!=null&&hit.GetComponentInParent<UnityEngine.UI.Button>()==button){UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(hit,Event(p),UnityEngine.EventSystems.ExecuteEvents.pointerClickHandler);return true;}}return false;}
void Expanded(bool value)=>typeof(ForgeBattlefieldController).GetMethod("SetRedesignHandExpanded",flags).Invoke(ui,new object[]{value});
void Quiet(){foreach(var p in UnityEngine.Object.FindObjectsByType<ForgeBattlefieldCardPointer>(FindObjectsSortMode.None))p.ResetHover();typeof(ForgeBattlefieldController).GetMethod("LeaveInspectCard",flags).Invoke(ui,null);}
System.Collections.IEnumerator Wait(float t=.2f){yield return new WaitForSecondsRealtime(t);Canvas.ForceUpdateCanvases();}
System.Collections.IEnumerator Present(ForgeSeatView v,int seat=1,bool clear=true){if(clear){ui.Present(null,seat,false,null,null,"");yield return null;}ui.Present(v,seat,true,i=>{calls++;last=i;},null,"本地界面验证");Quiet();yield return Wait();}
ForgeBattlefieldCardPointer[] Other()=>Root().Find("OpponentHandRoot").GetComponentsInChildren<ForgeBattlefieldCardPointer>().Where(p=>p.gameObject.activeInHierarchy).ToArray();
bool Visible(ForgeBattlefieldCardPointer p)=>p.GetComponent<CanvasGroup>().alpha>.02f;
void Clearance(string context){var field=Root().Find("ForgePermanents").GetComponentsInChildren<ForgeBattlefieldCardPointer>().Where(p=>p.gameObject.activeInHierarchy).ToArray();var pool=Root().Find("PublicManaPool");int n=0;foreach(var p in Other().Where(Visible)){var b=Bounds((RectTransform)p.transform);foreach(var f in field)if(Overlap(b,Bounds((RectTransform)f.transform)))n++;if(pool!=null&&Overlap(b,Bounds((RectTransform)pool)))n++;}Check(n==0,context+" resting opponent cards clear battlefield and mana");}
var assembly=typeof(UnityEditor.Editor).Assembly;var gameViewType=assembly.GetType("UnityEditor.GameView");var gameView=UnityEditor.EditorWindow.GetWindow(gameViewType);var sizeProperty=gameViewType.GetProperty("selectedSizeIndex",System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);int savedSize=(int)sizeProperty.GetValue(gameView);var sizesType=assembly.GetType("UnityEditor.GameViewSizes");var sizes=typeof(UnityEditor.ScriptableSingleton<>).MakeGenericType(sizesType).GetProperty("instance").GetValue(null);var group=sizesType.GetMethod("GetGroup").Invoke(sizes,new object[]{Enum.Parse(assembly.GetType("UnityEditor.GameViewSizeGroupType"),"Standalone")});var added=new System.Collections.Generic.List<int>();
void Resize(int w,int h){int index=((string[])group.GetType().GetMethod("GetDisplayTexts").Invoke(group,null)).Length;var size=Activator.CreateInstance(assembly.GetType("UnityEditor.GameViewSize"),new object[]{Enum.Parse(assembly.GetType("UnityEditor.GameViewSizeType"),"FixedResolution"),w,h,"MTGB opponent horizontal"});group.GetType().GetMethod("AddCustomSize").Invoke(group,new[]{size});added.Add(index);sizeProperty.SetValue(gameView,index);gameView.Repaint();}
void Restore(){GamePreferences.SetLanguage(oldLanguage);GamePreferences.SetScale(oldScale);sizeProperty.SetValue(gameView,savedSize);var labels=(string[])group.GetType().GetMethod("GetDisplayTexts").Invoke(group,null);for(int i=labels.Length-1;i>=0;i--)if(labels[i].StartsWith("MTGB opponent horizontal"))group.GetType().GetMethod("RemoveCustomSize").Invoke(group,new object[]{i});}
ForgeSeatView Many(int observer,int count,bool dense){var v=Sample();v.seat=observer;v.awaitingInput=false;v.request=new ForgeRequest{options=Array.Empty<ForgeOption>()};var own=v.players.First(p=>p.seat==observer);var other=v.players.First(p=>p.seat!=observer);if(own.hand.Length==0){own.hand=Sample().players[0].hand.Select(Clone).ToArray();foreach(var c in own.hand)c.ownerSeat=observer;own.handCount=own.hand.Length;}other.hand=Array.Empty<ForgeCardView>();other.handCount=count;other.publicPlayableExile=Array.Empty<ForgeCardView>();if(dense){var land=other.battlefield.First(c=>c.land);other.battlefield=other.battlefield.Concat(Enumerable.Range(0,20).Select(i=>{var c=Clone(land);c.id=88000+i;c.name="Layout land "+i;c.tapped=i%2==0;return c;})).ToArray();}return v;}
System.Collections.IEnumerator Run(){
 GamePreferences.SetLanguage("zh-CN");GamePreferences.SetScale(1);yield return null;while(!GamePreferences.Ready)yield return null;
 foreach(var size in new[]{new Vector2Int(1920,1080),new Vector2Int(1280,720),new Vector2Int(1024,768)}){
  Resize(size.x,size.y);yield return Wait();
  foreach(int observer in new[]{1,2})foreach(int count in new[]{0,1,7,24}){
   var v=Many(observer,count,count==24);yield return Present(v,observer);Expanded(true);yield return Wait(.05f);string context=size+" seat"+observer+" hand"+count;var hand=(RectTransform)Root().Find("OpponentHandRoot");var own=(RectTransform)Root().Find("PlayerHandRoot");var cards=Other();
   Check(cards.Length==count,context+" correct anonymous hand count");Check(cards.All(p=>Mathf.Abs(Mathf.DeltaAngle(p.transform.eulerAngles.z,180))<.1f&&Mathf.Abs(((RectTransform)p.transform).rect.width-166)<.1f),context+" fixed-size horizontal inverted row");
   Check(cards.Length==0||cards.Max(p=>((RectTransform)p.transform).anchoredPosition.y)-cards.Min(p=>((RectTransform)p.transform).anchoredPosition.y)<.1f,context+" no fan arc");
   Check(cards.All(p=>p.GetComponent<BattlefieldRedesignHandInput>()==null),context+" remote cards never own local reveal input");Clearance(context);
   Vector3 topPosition=hand.position;var poses=cards.Select(p=>p.transform.position).ToArray();float raised=own.anchoredPosition.y;Expanded(false);yield return Wait(.05f);results.Add(new{context,raised,lowered=own.anchoredPosition.y,topBefore=topPosition.ToString(),topAfter=hand.position.ToString(),poseChanges=cards.Select((p,i)=>Vector3.Distance(p.transform.position,poses[i])).ToArray()});Check(own.anchoredPosition.y<raised-150&&Vector3.Distance(topPosition,hand.position)<.1f&&cards.Select((p,i)=>Vector3.Distance(p.transform.position,poses[i])<.1f).All(x=>x),context+" local tuck changes only local hand");Expanded(true);
   var serialized=JsonUtility.ToJson(v);ui.Present(v,observer,true,i=>{calls++;last=i;},null,"");yield return Wait(.05f);Check(serialized==JsonUtility.ToJson(v)&&Vector3.Distance(topPosition,hand.position)<.1f,context+" repeated native snapshot preserves remote pose without writing view");
   if(count==24){var nav=hand.Find("HandFanNavigation").GetComponent<ForgeHandFanNavigation>();Check(nav.CanPan,context+" overflow pans");var next=nav.transform.Find("Next").GetComponent<UnityEngine.UI.Button>();Check(Click(next),context+" next arrow reachable outside stack");yield return Wait(.05f);Clearance(context+" paged");nav.MoveBy(-100000);yield return Wait(.05f);Check(cards.Single(p=>p.name=="Card_-24").GetComponent<CanvasGroup>().alpha>.9f,context+" final hidden card reachable");var prev=nav.transform.Find("Previous").GetComponent<UnityEngine.UI.Button>();Check(Click(prev),context+" previous arrow reachable");}
   if(size.x==1920&&observer==1&&count==7){Quiet();yield return Wait(.2f);ScreenCapture.CaptureScreenshot(W+"opponent-horizontal-own-raised.png");yield return new WaitForEndOfFrame();Expanded(false);yield return Wait(.1f);ScreenCapture.CaptureScreenshot(W+"opponent-horizontal-own-tucked.png");yield return new WaitForEndOfFrame();Expanded(true);}
   Save("RUNNING");
  }
 }
 Check(calls==0,"browsing/tucking both observer seats submits no game action");
 foreach(string lang in new[]{"zh-CN","en-US","ja-JP"}){
  GamePreferences.SetLanguage(lang);yield return null;while(!GamePreferences.Ready)yield return null;
  var pick=Read("D:/project/MTGB/Tools/Validation/Reports/Thoughtseize/choice.json");yield return Present(pick);Root().Find("OpponentHandRoot/HandFanNavigation").GetComponent<ForgeHandFanNavigation>().MoveBy(100000);yield return Wait(.1f);int option=Array.FindIndex(pick.request.options,o=>o.card!=null&&o.card.name=="Negate");var card=Other().First(p=>p.name=="Card_"+pick.request.options[option].card.id);var button=card.GetComponent<UnityEngine.UI.Button>();int before=calls;Check(Click(button),lang+" recorded Thoughtseize option reachable in resting new opponent row");Check(calls==before+1&&last==option,lang+" correct native option index submitted once");Click(button);Check(calls==before+1,lang+" duplicate click guarded");
  yield return Present(pick);Root().Find("OpponentHandRoot/HandFanNavigation").GetComponent<ForgeHandFanNavigation>().MoveBy(100000);yield return Wait(.1f);card=Other().First(p=>p.name=="Card_"+pick.request.options[option].card.id);Vector3 old=card.transform.position;card.OnPointerEnter(Event(Bounds((RectTransform)card.transform).center));yield return Wait(.5f);var face=(RectTransform)card.transform.Find("Visual");Check(Mathf.Abs(face.position.x-old.x)<1&&face.position.y<old.y-50&&Mathf.Abs(Mathf.DeltaAngle(face.eulerAngles.z,0))<1,lang+" revealed hover moves straight inward and is upright");card.OnPointerExit(Event(Vector2.zero));
  var hidden=Read("D:/project/MTGB/Tools/Validation/Reports/Thoughtseize/resolved.json");yield return Present(hidden);Check(Other().All(p=>int.Parse(p.name.Substring(5))<0),lang+" private hand replaces revealed identities with anonymous backs");
 }
 Resize(1920,1080);GamePreferences.SetLanguage("zh-CN");yield return null;while(!GamePreferences.Ready)yield return null;var final=Many(1,7,false);yield return Present(final);Expanded(true);Quiet();yield return Wait(.3f);ScreenCapture.CaptureScreenshot(W+"opponent-horizontal-own-raised.png");yield return new WaitForEndOfFrame();Restore();Save("COMPLETE");
}
System.Collections.IEnumerator Guard(){var it=Run();for(int i=0;i<100000;i++){bool next=false;object value=null;try{next=it.MoveNext();if(next)value=it.Current;}catch(Exception e){failed++;results.Add(new{exception=e.ToString()});Restore();Save("ERROR");yield break;}if(!next)break;yield return value;}}
Save("STARTING");ui.StartCoroutine(Guard());return "Opponent horizontal hand validation started";
